CREATE DATABASE IF NOT EXISTS SetupDino CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE SetupDino;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,description TEXT,price DECIMAL(10,2) NOT NULL,stock INT UNSIGNED NOT NULL DEFAULT 0,image VARCHAR(255),featured BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_product_category FOREIGN KEY(category_id) REFERENCES categories(id),CONSTRAINT chk_product_price CHECK(price>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,total DECIMAL(10,2) NOT NULL,status ENUM('pending','paid','shipped','delivered','cancelled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_order_user FOREIGN KEY(user_id) REFERENCES users(id),CONSTRAINT chk_order_total CHECK(total>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,unit_price DECIMAL(10,2) NOT NULL,CONSTRAINT fk_item_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,CONSTRAINT fk_item_product FOREIGN KEY(product_id) REFERENCES products(id),CONSTRAINT chk_item_quantity CHECK(quantity>0),CONSTRAINT chk_item_price CHECK(unit_price>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL UNIQUE,recipient_name VARCHAR(120) NOT NULL,postal_code VARCHAR(12) NOT NULL,street VARCHAR(180) NOT NULL,number VARCHAR(20) NOT NULL,complement VARCHAR(100),neighborhood VARCHAR(120) NOT NULL,city VARCHAR(120) NOT NULL,state CHAR(2) NOT NULL,CONSTRAINT fk_address_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
